package github.com.dappermickie.locationsharer;

import java.awt.*;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

public class LocationSharerPanel extends PluginPanel
{
    private final JLabel status;

    public LocationSharerPanel(Runnable onCopy, Runnable onPaste)
    {
        setLayout(new BorderLayout());
        JPanel content = new JPanel();
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBorder(new EmptyBorder(20, 12, 20, 12));
        JLabel title = new JLabel("Location Sharer");
        title.setFont(title.getFont().deriveFont(Font.BOLD, 19f));
        content.add(title);
        content.add(Box.createVerticalStrut(8));
        content.add(new JLabel("<html>Share a tile. Find your way there.</html>"));
        content.add(Box.createVerticalStrut(24));
        JButton copy = new JButton("Copy Current Location");
        JButton paste = new JButton("Paste Location for Shortest Path");
        for (JButton button : new JButton[]{copy, paste})
        {
            button.setAlignmentX(Component.LEFT_ALIGNMENT);
            button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));
            button.setMargin(new Insets(10, 4, 10, 4));
            content.add(button);
            content.add(Box.createVerticalStrut(10));
        }
        content.add(Box.createVerticalStrut(12));
        content.add(new JLabel("<html><b>Shortest Path required</b><br>Install and enable Shortest Path from<br>the Plugin Hub to show a route.</html>"));
        content.add(Box.createVerticalStrut(18));
        status = new JLabel("<html>Copy your tile or paste a shared location.</html>");
        status.setForeground(new Color(170, 190, 200));
        content.add(status);
        copy.addActionListener(e -> onCopy.run());
        paste.addActionListener(e -> onPaste.run());
        add(content, BorderLayout.NORTH);
    }

    public void setStatus(String text)
    {
        status.setText("<html>" + text + "</html>");
    }
}

package github.com.dappermickie.locationsharer;

import com.google.gson.Gson;
import com.google.gson.JsonObject;

import java.util.Collections;
import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(name = "Location Sharer", description = "Copy and share locations. Requires Shortest Path installed and enabled to show routes.", tags = {"location", "share", "clipboard", "coordinates", "shortest path", "navigation", "route", "friends"})
public class LocationSharerPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private EventBus eventBus;
    @Inject private Gson gson;
    @Inject private LocationSharerSidebar sidebar;
    private volatile boolean active;

    @Override
    protected void startUp()
    {
        active = true;
        sidebar.open(this::copyLocation, this::pasteLocation);
    }

    private void message(String text)
    {
        sidebar.setStatus(text);
    }
    private void copyLocation()
    {
        clientThread.invoke(() -> {
            if (!active) return;
            if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
            {
                message("Log in before copying a location.");
                return;
            }
            if (client.isInInstancedRegion())
            {
                message("Locations inside instances cannot be shared reliably. Copy a tile outside the instance.");
                return;
            }
            WorldPoint point = client.getLocalPlayer().getWorldLocation();
            JsonObject data = new JsonObject();
            data.addProperty("type", "location-sharer");
            data.addProperty("version", 1);
            data.addProperty("x", point.getX());
            data.addProperty("y", point.getY());
            data.addProperty("plane", point.getPlane());
            String json = gson.toJson(data);
            sidebar.copyToClipboard(json);
        });
    }

    private void pasteLocation()
    {
        try
        {
            String text = sidebar.readClipboard();
            if (text == null || text.length() > 1024) throw new IllegalArgumentException();
            JsonObject data = gson.fromJson(text, JsonObject.class);
            if (data == null || !"location-sharer".equals(data.get("type").getAsString()) || integer(data, "version", 1, 1) != 1) throw new IllegalArgumentException();
            WorldPoint target = new WorldPoint(integer(data, "x", 0, 16383), integer(data, "y", 0, 16383), integer(data, "plane", 0, 3));
            clientThread.invoke(() -> {
                if (!active) return;
                if (client.getGameState() != GameState.LOGGED_IN) { message("Log in before requesting a route."); return; }
                eventBus.post(new PluginMessage("shortestpath", "path", Collections.singletonMap("target", target)));
                message("Route requested to " + target.getX() + ", " + target.getY() + " (plane " + target.getPlane() + ").<br>If no route appears, enable Shortest Path.");
            });
        }
        catch (Exception ex) { message("Copy a valid Location Sharer location first, then try again."); }
    }

    private static int integer(JsonObject data, String key, int min, int max)
    {
        String value = data.get(key).getAsString();
        if (!value.matches("[0-9]{1,5}")) throw new IllegalArgumentException();
        int number = Integer.parseInt(value);
        if (number < min || number > max) throw new IllegalArgumentException();
        return number;
    }

    @Override
    protected void shutDown()
    {
        active = false;
        sidebar.close();
    }
}

package github.com.dappermickie.locationsharer;

import java.awt.*;
import java.awt.datatransfer.*;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

public class LocationSharerSidebar
{
    @Inject private ClientToolbar toolbar;
    private NavigationButton navigation;
    private LocationSharerPanel panel;
    private volatile long generation;

    public void open(Runnable onCopy, Runnable onPaste)
    {
        long current = ++generation;
        SwingUtilities.invokeLater(() -> {
            if (current != generation) return;
            panel = new LocationSharerPanel(onCopy, onPaste);
            navigation = NavigationButton.builder().tooltip("Location Sharer")
                .icon(createIcon()).panel(panel).priority(6).build();
            toolbar.addNavigation(navigation);
        });
    }

    public void close()
    {
        ++generation;
        SwingUtilities.invokeLater(() -> {
            if (navigation != null) toolbar.removeNavigation(navigation);
            navigation = null;
            panel = null;
        });
    }

    public void setStatus(String text)
    {
        long current = generation;
        SwingUtilities.invokeLater(() -> {
            if (current == generation && panel != null) panel.setStatus(text);
        });
    }

    public void copyToClipboard(String text)
    {
        long current = generation;
        SwingUtilities.invokeLater(() -> {
            if (current != generation || panel == null) return;
            try
            {
                Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
                setStatus("Location copied. Share it with a friend.");
            }
            catch (IllegalStateException | HeadlessException ex)
            {
                setStatus("Clipboard unavailable. Please try again.");
            }
        });
    }

    public String readClipboard() throws Exception
    {
        return (String) Toolkit.getDefaultToolkit().getSystemClipboard().getData(DataFlavor.stringFlavor);
    }

    private static BufferedImage createIcon()
    {
            BufferedImage icon = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
            Graphics2D g = icon.createGraphics();
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setColor(new Color(110, 205, 225));
            g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            g.drawLine(5, 19, 19, 5);
            g.drawLine(9, 5, 19, 5);
            g.drawLine(19, 5, 19, 15);
            g.dispose();
        return icon;
    }
}

